const DEFAULT_TEXT_DIRECTION = 'ltr';

/**
 * Identifies the wrapper around `Editorial`. The wrapper, not the editor, is what carries the
 * hidden/shown state, so a test asserting that a message or spinner replaced the text on screen —
 * without the editor being torn down and rebuilt — has to address this element.
 */
export const MODEL_TEXT_EDITOR_CONTAINER_TEST_ID = 'model-text-editor-container';

// The editor's default view options never change, so build them once at module scope. Rebuilding a
// fresh `view` object inside the `options` memo would give `options` a new identity on every fetch,
// and the editor reloads (re-serialize + setEditorState) whenever the `view` object's identity
// changes — so a refetch of identical content would force a pointless full reload.
const VIEW_OPTIONS = getDefaultViewOptions();

export {
  MODEL_TEXT_PANEL_STRING_KEYS,
  type ModelTextPanelLocalizedStringKey,
  type ModelTextPanelLocalizedStrings,
} from './model-text-panel.const';

/**
 * Falls back to the key itself, matching the idiom in `book-not-available-view.component.tsx` and
 * `empty-chapter-view.component.tsx`. Falling back to `''` instead would render an empty message
 * region — a blank panel, which is the exact failure this panel's message exists to remove.
 */
const localize = (strings: ModelTextPanelLocalizedStrings, key: ModelTextPanelLocalizedStringKey) =>
  strings[key] ?? key;

const DEFAULT_SCR_REF: SerializedVerseRef = { book: 'GEN', chapterNum: 1, verseNum: 1 };

/**
 * How long a written pick waits for the list it wrote to arrive. An update normally lands within
 * moments of the write; this bounds the wait for one that never comes (the settings subscription
 * failed, say), which would otherwise leave "Selecting…" up until the panel is reloaded.
 */
export const WRITTEN_PICK_MAX_WAIT_MS = 10_000;

export type ModelTextPanelProps = {
  /** Localized strings; import `MODEL_TEXT_PANEL_STRING_KEYS` to resolve them. */
  localizedStrings: ModelTextPanelLocalizedStrings;
  /** Whether the panel has a project context (opened with a project id). */
  hasProject: boolean;
  /**
   * Readiness of the configured model-text list, passed as the whole discriminated state rather
   * than unpacked into a list plus a status.
   *
   * Unpacking it at this boundary would hand the panel an `undefined`-able list AND a loose status
   * string — two values free to disagree, which is precisely what the union exists to prevent. `{
   * status: 'ready', list: undefined }` and `{ status: 'loading' }` carrying a list are both
   * unrepresentable this way, and narrowing survives into the component. The first item of a
   * `ready` list is the configured model text. See `getResourcePanelReadiness` for how the panels
   * share their front-state derivation.
   */
  modelTextsState: EffectiveResourceReferenceListState;
  /** All DBL resources — used to match the configured model text and to feed the resource picker. */
  dblResources: DblResourceData[];
  /**
   * Whether the DBL resource catalog has finished loading AND delivered a real answer. Not the same
   * as "the fetch settled": `dblResources` coerces a missing or failed catalog to `[]`, which is
   * indistinguishable from a genuinely empty one.
   */
  isCatalogReady: boolean;
  /** Whether the DBL resource catalog fetch failed. Recoverable by re-fetching. */
  hasCatalogError: boolean;
  /** Re-runs the DBL resource catalog fetch. */
  onRetryCatalog: () => void;
  /** The function to get the user-level model-text setting (used when writing a user choice). */
  getUserModelTexts: () => Promise<ResourceReferenceList | undefined>;
  /** Current Scripture reference for the editor. */
  scrRef?: SerializedVerseRef;
  /** Called when the editor changes the Scripture reference. */
  onScrRefChange?: (scrRef: SerializedVerseRef) => void;
  /**
   * Install a DBL resource by its entry uid (fire-and-forget; the panel re-resolves once
   * installed).
   */
  installResource: (dblEntryUid: string) => Promise<void>;
  /** Persist a user-level model-text list. */
  setUserModelTexts: (list: ResourceReferenceList) => Promise<void>;
  /**
   * Open the resource picker for the user to choose a model text. Resolves with the chosen
   * resource, or `undefined` if the picker was cancelled. In the app this opens the
   * `platform.resourcePicker` dialog; in Storybook it renders the real ResourcePickerDialog
   * inline.
   */
  showResourcePicker: (selectedResourceIds: string[]) => Promise<DblResourceData | undefined>;
  /**
   * Retrieve the resolved resource's chapter USJ and text direction. This is a callback (not a
   * prop) because the resource project to read from is resolved inside this component.
   */
  getResourceChapter: (
    resourceProjectId: string,
    scrRef: SerializedVerseRef,
  ) => Promise<{ usj: Usj | undefined; textDirection: string }>;
  /**
   * The copy limit of the chapter `scrRef` points to in the project `getModelResourceProjectId`
   * resolves, as `useChapterCopyLimit` gives it. Required so a caller states it: `undefined` means
   * no limit, and `0`, the answer while the limit is unknown, blocks copying. The panel also blocks
   * copying while the chapter text loads.
   */
  resourceCopyLimit: number | undefined;
  /** Logger forwarded to the editor (the webview supplies the PAPI logger; stories may omit it). */
  logger?: ComponentProps<typeof Editorial>['logger'];
  /**
   * The model text's copyright notice, shown below the header. The web view supplies it because
   * reading the notice needs PAPI.
   */
  copyrightNotice?: ReactNode;
};

/**
 * Read-only panel that displays a project's configured "model text" Scripture resource. It owns the
 * orchestration (resolve the configured model text → match a DBL resource → auto-install if needed
 * → load that resource's chapter USJ) so the app webview and Storybook share the same logic; only
 * the data (props) and the PAPI-backed operations (callbacks) differ between them.
 */
export function ModelTextPanel({
  localizedStrings,
  hasProject,
  modelTextsState,
  dblResources,
  isCatalogReady,
  hasCatalogError,
  onRetryCatalog,
  getUserModelTexts,
  scrRef = DEFAULT_SCR_REF,
  onScrRefChange = () => {},
  installResource,
  setUserModelTexts,
  showResourcePicker,
  getResourceChapter,
  resourceCopyLimit,
  logger,
  copyrightNotice,
}: ModelTextPanelProps) {
  // --- Resolve the configured model text against the DBL resource list ---

  // Derived from the narrowed union, so it can only be non-undefined when the list is genuinely
  // ready — the invariant the prop shape now guarantees rather than merely documents.
  const effectiveModelTexts = modelTextsState.status === 'ready' ? modelTextsState.list : undefined;
  const effectiveModelText = effectiveModelTexts?.items[0];
  let dblRef: (EffectiveResourceReference & DblResourceReference) | undefined;
  if (isDblResourceReference(effectiveModelText)) dblRef = effectiveModelText;
  const match = dblRef ? findCachedDblResource(dblRef, dblResources) : undefined;
  const resourceProjectId = getModelResourceProjectId(effectiveModelText, dblResources);
  const modelTextLabel = effectiveModelText
    ? getRefLabel(effectiveModelText, dblResources)
    : undefined;
  // Admin items are listed first, so the text on screen is the user's own only while the admin has
  // chosen nothing. Only then can the user change it from this panel (the header and the
  // missing-book message offer the picker); the admin's choice is changed in the team layout.
  const isUserChosenModelText = effectiveModelText?.source === 'user';

  // Only show the tooltip when the label is actually clipped — an unconditional Tooltip would fire
  // on every hover, even when the full label already fits. The ref goes on the inner span that
  // carries the ellipsis, not the header box around it: the box is sized by the column and never
  // overflows, so measuring it would leave the tooltip permanently shut.
  const {
    ref: modelTextLabelRef,
    open: isModelTextLabelTruncatedHovered,
    onPointerEnter: onModelTextLabelPointerEnter,
    onPointerLeave: onModelTextLabelPointerLeave,
  } = useTruncationTooltip<HTMLSpanElement>();

  const [isSelecting, setIsSelecting] = useState(false);

  // Auto-install a matched-but-uninstalled configured model text (shared with the resource panel);
  // without it the panel spins forever with the picker unreachable. Skipped while a manual pick is
  // in flight (it installs the resource itself).
  const dblEntryUidToInstall = match && !match.installed ? match.dblEntryUid : undefined;
  const {
    isInstalling,
    installFailed,
    installFailureReason,
    retryInstall,
    clearInstallFailure,
    markInstallFailed,
  } = useDblResourceAutoInstall(dblEntryUidToInstall, installResource, {
    skipAutoInstall: isSelecting,
    refreshResourceList: onRetryCatalog,
  });

  // Only used to add a "check your connection" hint to the install-failed message when the machine
  // is definitely offline (the common cause of a failed download on first run).
  const isOnline = useIsOnline();

  // Tracks the latest scrRef this panel's editor just published so we can suppress the echo that
  // comes back through scroll group 0 (forced in simple mode) and avoid scroll-jumping the user's
  // own click target to the top of the viewport.
  const lastPublishedScrRefRef = useRef<SerializedVerseRef | undefined>(undefined);

  // --- Load the resolved resource's chapter USJ (re-fetch on resource/reference change) ---

  const [usj, setUsj] = useState<Usj | undefined>(undefined);
  const [textDirection, setTextDirection] = useState<string>(DEFAULT_TEXT_DIRECTION);
  // `undefined` means "not yet fetched" so we can show the loading state, matching the original.
  const [isUsjLoading, setIsUsjLoading] = useState(false);
  // The rejection itself is kept, not a boolean derived from it. `isMissingBookOnScreen` then decides
  // in the render body whether the failure still describes the book and model text on screen, so
  // navigating to a book this text does have cannot commit one frame still asserting the message.
  const [fetchError, setFetchError] = useState<unknown>(undefined);
  // WHICH request `usj`/`fetchError` are the answer to. Every state above survives a navigation —
  // `usj` still holds the previous chapter, `fetchError` the previous rejection — and the effect
  // that clears them runs after the commit, so the first render pairing a new reference with the
  // previous answer would otherwise read as an answer about the new one. That frame is what made a
  // step into a book the model text lacks paint "this chapter is empty" first. Comparing this key
  // against the reference being rendered makes the mismatched pairing unrepresentable instead of
  // merely brief.
  const [loadedRequestKey, setLoadedRequestKey] = useState<string | undefined>(undefined);

  const requestKey = `${resourceProjectId ?? ''}:${scrRef.book}:${scrRef.chapterNum}:${scrRef.versificationStr}`;

  useEffect(() => {
    if (!resourceProjectId) {
      setUsj(undefined);
      return undefined;
    }
    let isActive = true;
    setIsUsjLoading(true);
    setFetchError(undefined);
    const keyForThisLoad = requestKey;
    const load = async () => {
      const { usj: nextUsj, textDirection: nextTextDirection } = await getResourceChapter(
        resourceProjectId,
        scrRef,
      );
      if (!isActive) return;
      setUsj(nextUsj);
      setTextDirection(nextTextDirection || DEFAULT_TEXT_DIRECTION);
      setLoadedRequestKey(keyForThisLoad);
      setIsUsjLoading(false);
    };
    load().catch((e) => {
      if (!isActive) return;
      setUsj(undefined);
      setFetchError(e);
      setLoadedRequestKey(keyForThisLoad);
      setIsUsjLoading(false);
      // A missing book is ordinary navigation, not a fault, and it is already explained on screen —
      // so `debug`, which packaged builds drop entirely (`global-this.model.ts` runs at `info` when
      // packaged). That is deliberate rather than a gap: this fires once per resource per navigation
      // and the Scripture Text Grid can hit it for many cells at once, so `info` would be noise. It
      // is also safe, because the quiet path is the CORRECT one — if detection ever broke, the same
      // failure would fall to the `error` branch below and be loud in production, not silent.
      if (isMissingBookError(e))
        logger?.debug(`Book not found in model text: ${getErrorMessage(e)}`);
      else logger?.error(`Error getting model text chapter USJ: ${getErrorMessage(e)}`);
    });
    return () => {
      isActive = false;
    };
    // Intentionally excludes scrRef.verseNum: chapter data only changes with book or chapter, not
    // verse. Also excludes `logger`, used in the catch above: it is a stable module object, so
    // including it would only add a dep that never changes, and `requestKey`, which is built from
    // the four listed deps and so never changes independently of them.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    resourceProjectId,
    scrRef.book,
    scrRef.chapterNum,
    scrRef.versificationStr,
    getResourceChapter,
  ]);

  // Scroll to the current verse whenever the scrRef or USJ changes.
  // Using granular scrRef deps instead of the whole object avoids redundant scroll attempts
  // when scrRef identity changes but the reference itself hasn't.
  useEffect(() => {
    // Suppress our own echo: the panel is on scroll group 0 in simple mode, so a verse click
    // inside Editorial publishes to the scroll group and immediately bounces back as a prop
    // update. Without this check, scrollToVerse would snap the user's click target to the top
    // of the viewport after they clicked it.
    const lastPublished = lastPublishedScrRefRef.current;
    if (
      lastPublished &&
      lastPublished.book === scrRef.book &&
      lastPublished.chapterNum === scrRef.chapterNum &&
      lastPublished.verseNum === scrRef.verseNum
    ) {
      lastPublishedScrRefRef.current = undefined;
      return undefined;
    }

    // Gate on USJ being loaded for the current chapter. On book/chapter change, usj still holds
    // the previous chapter while the fetch is in flight — querying the DOM now would scroll into
    // the wrong chapter's content (or silently no-op). usj in deps ensures we re-run once data
    // arrives and the editor has re-rendered.
    if (!usj || isUsjLoading) return undefined;

    // rAF retry: waits for the editor DOM to paint the new chapter before scrolling. Stops as
    // soon as the verse element is found, or after SCROLL_MAX_WAIT_MS (verse marker absent).
    let cancelled = false;
    const start = Date.now();
    const tryScroll = () => {
      if (cancelled) return;
      const found = scrollToVerse(scrRef);
      if (found || scrRef.verseNum <= 1) return;
      if (Date.now() - start > SCROLL_MAX_WAIT_MS) return;
      requestAnimationFrame(tryScroll);
    };
    tryScroll();
    return () => {
      cancelled = true;
    };
    // scrollToVerse is a stable module-level import — adding it as a dep would cause spurious re-runs.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [usj, isUsjLoading, scrRef.book, scrRef.chapterNum, scrRef.verseNum]);

  // Whether `usj`/`fetchError` answer the reference currently being rendered. Everything below that
  // makes a claim about the model text is gated on this.
  const isAnswerCurrent = loadedRequestKey === requestKey;

  // See `blockCopyWhileChapterLoads` for why the limit is 0 while the chapter text loads. The text
  // in hand is loading from the render the reference changes, not only once the fetch starts.
  const copyLimit = blockCopyWhileChapterLoads(resourceCopyLimit, !isAnswerCurrent || isUsjLoading);

  // A chapter the resource HAS but with nothing in it. Gated on the answer in hand being for this
  // reference, because `usj` keeps the previous chapter's content until the new fetch lands —
  // deriving this from stale content would paint the message over a chapter that is still arriving,
  // or over a book the model text does not have at all.
  //
  // Chapter 0 is front matter rather than a chapter; `isBlankChapterOnScreen` has that rationale.
  const isBlankChapter = useMemo(
    () => isAnswerCurrent && !isUsjLoading && isBlankChapterOnScreen(usj, scrRef.chapterNum),
    [isAnswerCurrent, usj, isUsjLoading, scrRef.chapterNum],
  );

  // Whether the failure in hand still describes what this panel is showing. Derived rather than
  // latched in the `catch` so it is accurate for the render it is used in.
  const isBookMissing =
    isAnswerCurrent &&
    isMissingBookOnScreen({
      error: fetchError,
      currentBookNum: Canon.bookIdToNumber(scrRef.book),
      projectId: resourceProjectId,
    });

  // A failure that is not a missing book in the text on screen: an unreadable project, a permissions
  // failure, a data provider that cannot open the resource. Terminal, because the fetch already
  // rejected and nothing retries it until the reference or the model text changes — so a spinner
  // would claim progress that never arrives.
  //
  // A missing-book rejection naming some OTHER book or model text is excluded rather than treated as
  // a fault: that is the previous reference's answer, and `isAnswerCurrent` will clear it as soon as
  // the current fetch lands.
  const isTextUnavailable =
    isAnswerCurrent &&
    fetchError !== undefined &&
    !isBookMissing &&
    !isMissingBookError(fetchError);

  // --- Editor ---

  // EditorRef requires null initial value per React ref convention
  // eslint-disable-next-line no-null/no-null
  const editorRef = useRef<EditorRef | null>(null);
  // Markers this resource's content actually uses, so the editor doesn't warn "Unexpected <kind>
  // marker" for handbook/commentary markers (e.g. \pn, \jmp). Scoped per-resource from the displayed
  // USJ — never a global list — and additive, so listing built-in markers is a harmless no-op. The
  // returned array keeps a stable identity while the marker set is unchanged, so `options` below
  // doesn't churn (and reload the editor) on every fetch of identical content.
  const extraValidMarkers = useExtraValidMarkers(usj);

  const options: EditorOptions = useMemo(
    () => ({
      isReadonly: true,
      hasSpellCheck: false,
      // Opt-in: omit `nodes` entirely when there are no extra markers (no behavior change), matching
      // resource-text-panel.
      ...(extraValidMarkers.length > 0 ? { nodes: { extraValidMarkers } } : {}),
      // Narrow the resource's (string) text-direction setting to ltr or rtl. A project always
      // declares one of the two (direction cannot be guessed for a minority language), so the
      // editor's `auto` is not a mode core passes; anything else falls back to ltr.
      textDirection: textDirection === 'rtl' ? 'rtl' : 'ltr',
      view: VIEW_OPTIONS,
      copyLimit,
    }),
    [textDirection, extraValidMarkers, copyLimit],
  );

  // Read-only: push incoming USJ directly into the editor whenever it changes. This effect is the
  // editor's only feed, and `renderContent` below hides `Editorial` rather than unmounting it, so
  // one instance is fed for the panel's lifetime — a message or a spinner taking the content area
  // never costs the editor its content.
  useEffect(() => {
    if (usj) editorRef.current?.setUsj(usj);
  }, [usj]);

  // --- Resource picker / selection ---

  // The picker lists these as "Already selected" and won't let them be picked. Every pick stays in
  // the user's list behind the newer ones, so only the text on screen is passed: an earlier pick
  // must stay pickable.
  const currentModelTextId = effectiveModelText && getResourceReferenceBareId(effectiveModelText);
  const currentModelTextIds = useMemo(
    () => (currentModelTextId ? [currentModelTextId] : []),
    [currentModelTextId],
  );

  // The list on screen when a pick was written. Until a newer list arrives, the panel would show the
  // text being replaced again, so the pick still counts as in progress. It waits for a newer list
  // rather than for the picked id, because an admin item listed first would keep that id off screen.
  // "Newer" is by identity: every update from `useEffectiveResourceReferenceList` is a new object.
  // If none arrives within `WRITTEN_PICK_MAX_WAIT_MS`, the panel stops waiting and shows the list it
  // has.
  const [listBeforeWrittenPick, setListBeforeWrittenPick] = useState<
    EffectiveResourceReferenceList | undefined
  >(undefined);
  const isPickInProgress =
    isSelecting ||
    (listBeforeWrittenPick !== undefined && listBeforeWrittenPick === effectiveModelTexts);
  useEffect(() => {
    if (listBeforeWrittenPick === undefined) return undefined;
    if (listBeforeWrittenPick !== effectiveModelTexts) {
      setListBeforeWrittenPick(undefined);
      return undefined;
    }
    const timeout = setTimeout(() => setListBeforeWrittenPick(undefined), WRITTEN_PICK_MAX_WAIT_MS);
    return () => clearTimeout(timeout);
  }, [listBeforeWrittenPick, effectiveModelTexts]);

  // Read when a pick lands rather than when the picker opened, since the list can change while the
  // user is choosing.
  const effectiveModelTextsRef = useRef(effectiveModelTexts);
  effectiveModelTextsRef.current = effectiveModelTexts;

  const handleResourceSelect = useCallback(
    async (resource: DblResourceData) => {
      const listBeforePick = effectiveModelTextsRef.current;
      setIsSelecting(true);
      // A user-initiated pick is a fresh attempt: clear any prior auto-install failure so the
      // install-failed state doesn't stick.
      clearInstallFailure();
      try {
        await selectTextConnection(
          resource,
          getUserModelTexts,
          setUserModelTexts,
          async () => {
            try {
              await installResource(resource.dblEntryUid);
            } catch (e) {
              // Record the failure so that once the pick finishes and the auto-install effect
              // re-enables, its failed-uid guard suppresses a duplicate install attempt.
              //
              // TODO(PT-4508): This does NOT surface the failure on screen. `selectTextConnection`
              // swallows the rethrow below and returns without persisting, so the text on screen
              // never changes and `installFailed` never becomes true — a failed pick is silent.
              markInstallFailed(resource.dblEntryUid);
              throw e;
            }
          },
          (writtenReference) => {
            // Re-picking the user's first text writes an identical list, which sends no update, so
            // there would be no newer list to wait for.
            const firstUserText = listBeforePick?.items.find((item) => item.source === 'user');
            const isListUnchanged =
              firstUserText !== undefined &&
              getResourceReferenceRowId(firstUserText) ===
                getResourceReferenceRowId(writtenReference);
            if (!isListUnchanged) setListBeforeWrittenPick(listBeforePick);
          },
        );
      } finally {
        setIsSelecting(false);
      }
    },
    [getUserModelTexts, setUserModelTexts, installResource, clearInstallFailure, markInstallFailed],
  );

  // One pick at a time. The Pick button stays enabled while the picker is open and while a picked
  // resource installs, and a second pick would either replace the open picker (the dialog service
  // rejects the first with an error that reaches us without its code) or race a pick whose resource
  // is still installing and let the older pick's write land last.
  const isPickingRef = useRef(false);

  // A pick from the missing-book message replaces its button with "Selecting…", so focus falls to
  // `body`; once the pick is over and the content below the header has arrived, it goes to the
  // header. Waiting for the content lets a message that arrives instead (the picked text lacks this
  // book too, say) take focus itself, so it is announced rather than appearing silently beside a
  // focused header. A header pick keeps focus, since the header stays mounted.
  //
  // Runs after every commit, rather than on a change of the conditions below, so a header that only
  // comes back after the pick (a catalog refresh can hide the whole panel) is still found. A passive
  // effect runs after its children's, so a message mounted in the same commit has already taken
  // focus by then.
  // Using null for React ref compatibility
  // eslint-disable-next-line no-null/no-null
  const headerButtonRef = useRef<HTMLButtonElement | null>(null);
  const shouldFocusHeaderAfterPickRef = useRef(false);
  useEffect(() => {
    const header = headerButtonRef.current;
    if (!header || !shouldFocusHeaderAfterPickRef.current) return;
    if (isPickInProgress || !isAnswerCurrent || isUsjLoading) return;
    shouldFocusHeaderAfterPickRef.current = false;
    if (isFocusDroppedInThisDocument()) header.focus();
  });

  // Called from click handlers, which nothing awaits, so a failure is caught here or nowhere. The
  // log names the resource once one was picked, so a failed settings read or write (which has no UI
  // of its own) can be told apart from a picker that failed to open.
  const handlePickModelText = useCallback(async () => {
    if (isPickingRef.current) return;
    isPickingRef.current = true;
    let resource: DblResourceData | undefined;
    try {
      resource = await showResourcePicker(currentModelTextIds);
      if (resource) {
        // Only a pick made beside the header returns focus to it.
        shouldFocusHeaderAfterPickRef.current = Boolean(headerButtonRef.current);
        await handleResourceSelect(resource);
      }
    } catch (e) {
      const stage = resource ? `selecting ${resource.dblEntryUid}` : 'opening the picker';
      logger?.error(`Model text selection failed while ${stage}: ${getErrorMessage(e)}`);
    } finally {
      isPickingRef.current = false;
    }
  }, [showResourcePicker, currentModelTextIds, handleResourceSelect, logger]);

  const handleScrRefChange = useCallback(
    (newScrRef: SerializedVerseRef) => {
      lastPublishedScrRefRef.current = newScrRef;
      onScrRefChange(newScrRef);
    },
    [onScrRefChange],
  );

  // --- Render the resolved state ---

  // Not-found: a configured model text can't be resolved to a displayable resource (not in the DBL
  // catalog, a non-DBL reference, or an entry missing its id). For the user's own text, offer the
  // picker so they are not stranded. A pick could never replace the admin's text, so that case says
  // where it can be changed instead.
  const notFoundState = (
    <div
      className={`tw:flex tw:flex-col tw:items-center tw:gap-4 tw:p-8 tw:text-center ${PANEL_FILL_CLASSES}`}
    >
      {isUserChosenModelText ? (
        <>
          <p>{localize(localizedStrings, '%webView_modelTextPanel_unknownResource%')}</p>
          <Button onClick={() => handlePickModelText()}>
            {localize(localizedStrings, '%webView_modelTextPanel_pickModelText%')}
          </Button>
        </>
      ) : (
        <p>{localize(localizedStrings, '%webView_modelTextPanel_unknownResource_adminChoice%')}</p>
      )}
    </div>
  );

  // No project: opened without a project id (expected to be brief).
  if (!hasProject) {
    return (
      <div className="tw:flex tw:h-screen tw:items-center tw:justify-center tw:p-8 tw:text-center">
        <p>{localize(localizedStrings, '%webView_modelTextPanel_noProject%')}</p>
      </div>
    );
  }

  // A pick with no text on screen to keep: from the empty state, from a not-found state, or with the
  // panel hidden by a catalog refresh. Checked before those states return, because a picked text
  // that isn't installed downloads before the pick is written, and until then the state the user
  // picked from would stay on screen, Pick button included. A pick made while a text is on screen
  // waits in the content area instead (see `renderContent`), so the header and the hidden editor
  // stay mounted.
  if (isPickInProgress && !resourceProjectId) {
    return <LoadingView label={localize(localizedStrings, '%webView_modelTextPanel_selecting%')} />;
  }

  // Front of the state machine: still resolving, an unreadable setting, a catalog that failed, or
  // genuinely nothing configured. Derived from one readiness value and rendered by the same view
  // the Resource panel uses, so the two panels cannot drift apart on the question that caused this
  // bug in the first place.
  const readiness = getResourcePanelReadiness({
    listState: modelTextsState,
    isCatalogReady,
    hasCatalogError,
    // `matchingCount` is omitted: this panel shows the first configured model text whatever its
    // type, so every configured item matches — unlike the Resource panel, which filters by type.
  });

  if (readiness !== 'configured') {
    return (
      <PanelReadinessView
        readiness={readiness}
        errorMessage={localize(localizedStrings, '%webView_modelTextPanel_settingsUnavailable%')}
        catalogErrorMessage={localize(
          localizedStrings,
          '%webView_modelTextPanel_catalogUnavailable%',
        )}
        loadingLabel={localize(localizedStrings, '%webView_modelTextPanel_loading%')}
        emptyPrompt={formatReplacementString(
          localize(localizedStrings, '%webView_modelTextPanel_emptyState_baseOrModel_prompt%'),
          {
            summary: localize(
              localizedStrings,
              '%webView_modelTextPanel_emptyState_baseOrModel_summary%',
            ),
          },
        )}
        moreInfo={
          <ExpandableInfo
            moreLabel={localize(localizedStrings, '%webView_modelTextPanel_emptyState_moreInfo%')}
            lessLabel={localize(localizedStrings, '%webView_modelTextPanel_emptyState_lessInfo%')}
            body={
              // Start-aligned and normally wrapped, unlike the centered, balanced empty state
              // around it, so the bold terms line up and it reads like the Team layout dialog's.
              <BaseOrModelTextExplanation
                localizedStrings={localizedStrings}
                className="tw:text-start tw:text-wrap"
              />
            }
          />
        }
        pickLabel={localize(localizedStrings, '%webView_modelTextPanel_emptyState_pickText%')}
        retryLabel={localize(localizedStrings, '%webView_modelTextPanel_retry%')}
        onPick={() => handlePickModelText()}
        onRetryCatalog={onRetryCatalog}
      />
    );
  }

  // Error state: the configured uid isn't in the DBL list at all. Reachable only once the catalog
  // has arrived, so this is now a fact rather than a guess.
  if (dblRef && match === undefined) {
    return notFoundState;
  }

  // Install failed: the resource is in the catalog but couldn't be installed. Offer a retry rather
  // than spinning forever. Retry re-attempts the same (admin or user) configured resource, so an
  // admin choice is recoverable too; a success drops out of this state on its own. When offline
  // (the usual first-run cause), hint at the connection.
  if (installFailed) {
    return (
      <PanelRetryableErrorView
        message={localize(
          localizedStrings,
          getInstallFailureMessageKey(
            installFailureReason,
            isOnline,
            MODEL_TEXT_PANEL_INSTALL_FAILURE_KEYS,
          ),
        )}
        retryLabel={localize(localizedStrings, '%webView_modelTextPanel_retry%')}
        onRetry={retryInstall}
      />
    );
  }

  // Installing: an auto-install of a configured resource, where the user picked nothing and it's
  // just downloading, reads "Installing…". One that overlaps a pick reads "Selecting…", like the
  // pick.
  if (isInstalling) {
    return (
      <LoadingView
        label={localize(
          localizedStrings,
          isPickInProgress
            ? '%webView_modelTextPanel_selecting%'
            : '%webView_modelTextPanel_installing%',
        )}
      />
    );
  }

  // Unresolvable: a model text is configured but doesn't resolve to a displayable installed
  // resource (e.g. a non-DBL reference, or a DBL entry missing its id). Show the not-found state
  // rather than an endless spinner. By here resources have loaded and any matched-but-uninstalled
  // resource was handled above, so this is a terminal state.
  if (!resourceProjectId) {
    return notFoundState;
  }

  // The model text, or the reason there is none. These are the panel's CONTENT area only: the label
  // header stays mounted above all of them, including the spinner, so the message is attributed to a
  // named text rather than floating in an anonymous panel and does not blink away on every chapter
  // step.
  //
  // A pick in progress takes the content area too: it hides the editor rather than unmounting it, so
  // the editor still holds its text if the pick changes nothing.
  //
  // A blank chapter is one the model text HAS but with nothing in it. It is invisible to
  // `isBookMissing`, which keys off the fetch rejecting, so it needs its own check; the missing book
  // is tested first because it is the more specific claim. Without the blank-chapter arm the
  // read-only editor renders with nothing set and shows `Editorial`'s "enter some Scripture" prompt
  // — an edit invitation in a text the reader cannot edit.
  //
  // Only the editor gets `dir`. That is the RESOURCE's text direction, and the messages are app
  // chrome: inheriting it would lay a left-to-right UI string out right-to-left whenever the model
  // text is RTL.
  const renderContent = () => {
    const message = (() => {
      if (isPickInProgress)
        return (
          <LoadingView
            label={localize(localizedStrings, '%webView_modelTextPanel_selecting%')}
            heightClassName="tw:h-full"
          />
        );

      if (isBookMissing)
        return (
          <ResourceBookNotAvailable
            message={localize(
              localizedStrings,
              isUserChosenModelText
                ? '%webView_modelTextPanel_bookNotAvailable%'
                : '%webView_modelTextPanel_bookNotAvailable_adminChoice%',
            )}
            announcementKey={`${resourceProjectId}:${scrRef.book}`}
            action={
              isUserChosenModelText
                ? {
                    label: localize(localizedStrings, '%webView_modelTextPanel_pickModelText%'),
                    onClick: () => handlePickModelText(),
                  }
                : undefined
            }
          />
        );

      if (isBlankChapter)
        return (
          <ResourceBlankChapter
            message={localize(
              localizedStrings,
              '%webView_platformScriptureEditor_emptyChapter_messageResource%',
            )}
            announcementKey={`${resourceProjectId}:${scrRef.book}:${scrRef.chapterNum}`}
          />
        );

      if (isTextUnavailable)
        return (
          <ResourceTextUnavailable
            message={localize(localizedStrings, '%webView_resourcePanel_textUnavailable%')}
            announcementKey={`${resourceProjectId}:${scrRef.book}:${scrRef.chapterNum}`}
          />
        );

      return undefined;
    })();

    // Nothing to say and nothing in hand yet: the fetch for this reference is still out.
    const isWaiting = !message && (!isAnswerCurrent || isUsjLoading || usj === undefined);

    return (
      <>
        {message && <div className="tw:flex-1 tw:overflow-auto">{message}</div>}
        {isWaiting && (
          <div className="tw:flex tw:flex-1 tw:items-center tw:justify-center tw:p-8">
            <Spinner />
          </div>
        )}
        {/*
          `Editorial` is HIDDEN rather than unmounted whenever something else occupies the content
          area. Unmounting it disposes the whole `LexicalComposer` — plugins and nodes deregister,
          the DOM is torn down — and bringing it back costs a full rebuild plus a whole-chapter
          `setUsj`. `isWaiting` is true from the instant the reference changes until the round trip
          completes, so unmounting on it would pay that price on every chapter step, the panel's
          primary interaction. Hiding keeps one editor instance for the panel's lifetime; the main
          editor hides its subtree the same way behind `EmptyChapterView`.

          `tw:hidden` is `display: none`, which also takes the editor out of the accessibility tree
          and the tab order while a message is showing — wanted here, since the message is the thing
          to read and this panel is read-only, so there is nothing in the editor to reach.
        */}
        <div
          data-testid={MODEL_TEXT_EDITOR_CONTAINER_TEST_ID}
          className={message || isWaiting ? 'tw:hidden' : 'tw:flex-1 tw:overflow-auto'}
          dir={options.textDirection}
        >
          {/* The zoom marker sits INSIDE the scroll box, never on it or above it:
              `scrollToVerse` adds a `getBoundingClientRect()` distance (zoomed pixels) to the
              box's `scrollTop` (unzoomed pixels), which agree only while the box itself is
              unscaled. Named as its own zoom area ("model-text") so its remembered level is kept
              apart from this project's other resource panes, which resolve to the same
              kind/identity pair and would otherwise all read one remembered level. The messages
              and the spinner are app chrome and stay unmarked. */}
          <ContentZoomRoot area="model-text">
            <Editorial
              ref={editorRef}
              scrRef={scrRef}
              onScrRefChange={handleScrRefChange}
              options={options}
              logger={logger}
            />
          </ContentZoomRoot>
        </div>
      </>
    );
  };

  // The model text header row, shared by the label and button forms of the header.
  //
  // 42px total, matching Column 3's dock tab-bar OUTER height (the 36px active tab plus its 6px
  // --tab-header-to-content-gap) and the Scripture Editor's Simple-mode toolbar override — all three
  // rows' bottom edges need to land at the same Y, which matching total row height achieves on its
  // own. `tw:items-center` centers the text symmetrically within the full 42px box (no extra
  // top-only padding needed — see _simple-mode.scss's .scripture-editor-tab-nav-simple comment for
  // why that was tried and reverted).
  //
  // Truncation + Tooltip: the column has a ~300px minWidth (simple-layout.data.ts) and the
  // "{displayName} - {fullName}" label can exceed it, so the label ellipsises to keep the fixed 42px
  // row height intact, with the full text on hover/focus per the Responsiveness guideline.
  // `tw:min-w-0` unlocks the shrink that `tw:overflow-hidden` then bounds.
  const modelTextHeaderClassName =
    'tw:flex tw:h-[42px] tw:min-w-0 tw:shrink-0 tw:items-center tw:overflow-hidden tw:border-b tw:border-border tw:px-3 tw:text-sm tw:font-semibold';

  // The header's text. `dir="auto"`: the label is a joined short/full name in one text node, so it
  // carries its own direction rather than the panel's. The ellipsis lives here rather than on the
  // header box: `text-overflow` is inert on a flex container, because the text becomes an anonymous
  // flex item and hard-clips mid-glyph.
  const modelTextHeaderLabel = (
    <span ref={modelTextLabelRef} className="tw:min-w-0 tw:truncate" dir="auto">
      {modelTextLabel}
    </span>
  );

  // Active: read-only editor showing the model text.
  // This panel is Simple-mode-only, so `editor-container-simple` (flattens .editor-container's
  // rounded top corners — see _simple-mode.scss) is applied unconditionally, unlike the
  // Scripture Editor's conditional use of the same class.
  return (
    <div className="tw:flex tw:h-screen tw:flex-col editor-container-simple">
      {modelTextLabel && (
        <TooltipProvider>
          <Tooltip
            open={isModelTextLabelTruncatedHovered}
            // Lets Escape, a press on the header, and leaving it close the tooltip. Opening stays
            // with the truncation check, so a label that fits never gets one.
            onOpenChange={(open) => {
              if (!open) onModelTextLabelPointerLeave();
            }}
          >
            {/* Both header forms take these from the trigger. Focus opens the tooltip only on a
                keyboard arrival (`:focus-visible`): focus returned to the header after a pointer
                pick, or moved there by the panel, must not pop it up. */}
            <TooltipTrigger
              asChild
              onPointerEnter={onModelTextLabelPointerEnter}
              onPointerLeave={onModelTextLabelPointerLeave}
              onFocus={(event) => {
                if (event.currentTarget.matches(':focus-visible')) onModelTextLabelPointerEnter();
              }}
              onBlur={onModelTextLabelPointerLeave}
              data-testid="model-text-header"
            >
              {isUserChosenModelText ? (
                <Button
                  ref={headerButtonRef}
                  variant="ghost"
                  // The picker is a modal dialog. This also turns off `Button`'s 1px press nudge,
                  // which would shift the whole row out of line with the editor toolbar.
                  aria-haspopup="dialog"
                  onClick={() => {
                    // A keyboard press fires no pointer event, so close the tooltip here too.
                    onModelTextLabelPointerLeave();
                    handlePickModelText();
                  }}
                  aria-label={formatReplacementString(
                    localize(localizedStrings, '%webView_modelTextPanel_changeText_ariaLabel%'),
                    { textName: modelTextLabel },
                  )}
                  // `tw:border-0` clears `Button`'s border on every side, and must come BEFORE the
                  // row's `tw:border-b`: `Button` merges classes, so a later reset would drop the
                  // bottom rule. The ring is inset because the row touches the panel's top and side
                  // edges, which would clip one drawn outside it.
                  className={`tw:border-0 ${modelTextHeaderClassName} tw:w-full tw:justify-start tw:rounded-none tw:focus-visible:ring-inset`}
                >
                  {modelTextHeaderLabel}
                  {/* At the end edge, so it stays put whatever the name's length */}
                  <ChevronDown className="tw:ms-auto" />
                </Button>
              ) : (
                // Keyboard and screen-reader users can't hover, so this otherwise non-interactive
                // label is focusable to reach its tooltip. Matches the tooltip-trigger pattern in
                // platform-scripture-editor.web-view.tsx's structure-protection wrapper.
                // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex
                <div tabIndex={0} aria-label={modelTextLabel} className={modelTextHeaderClassName}>
                  {modelTextHeaderLabel}
                </div>
              )}
            </TooltipTrigger>
            <TooltipContent dir="auto">{modelTextLabel}</TooltipContent>
          </Tooltip>
        </TooltipProvider>
      )}
      {/* Below the header, so the header keeps the fixed 42px height that lines it up with
          Column 3's tab bar */}
      {copyrightNotice}
      {/* The label row stays outside the zoom area (marked inside the editor's scroll box in
          `renderContent`) so its pinned 42 px height — aligned with the editor's toolbar and
          Column 3's tab bar — doesn't scale with the content. */}
      <div className="tw:flex tw:flex-col tw:flex-1 tw:min-h-0">{renderContent()}</div>
    </div>
  );
}

export default ModelTextPanel;
